    public static function render(string $name, int $size = 20, ?string $label = null): string
    {
        if (! isset(self::MARKUP[$name])) {
            throw new \InvalidArgumentException("Unknown icon: {$name}");
        }

        $attributes = $label === null
            ? 'aria-hidden="true"'
            : 'role="img" aria-label="'.e($label).'"';

        return '<svg class="fb-icon'.($name === 'loader' ? ' fb-icon--loader' : '').'" width="'.$size.'" height="'.$size.'" viewBox="0 0 24 24" fill="none" '.$attributes.'>'.self::MARKUP[$name].'</svg>';
    }
}
